CREATE TABLE IF NOT EXISTS "PlatformIncidents" (id serial PRIMARY KEY,title varchar(160) NOT NULL,severity varchar(16) NOT NULL,component varchar(32) NOT NULL,status varchar(24) NOT NULL DEFAULT 'OPEN',summary text NOT NULL,"createdBy" integer NOT NULL,"resolvedAt" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS platform_incident_status ON "PlatformIncidents"(status,"updatedAt");
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='platform_incident_values' AND conrelid='"PlatformIncidents"'::regclass) THEN ALTER TABLE "PlatformIncidents" ADD CONSTRAINT platform_incident_values CHECK(severity IN ('LOW','MEDIUM','HIGH','CRITICAL') AND component IN ('API','DATABASE','CACHE','AUTH','BILLING','SUPPORT','OTHER') AND status IN ('OPEN','INVESTIGATING','MONITORING','RESOLVED')); END IF; END $$;
